CheckCommand:
SecEdit.exe /export /cfg $env:TEMP\secpol.cfg > $null
$cfg = Get-Content $env:TEMP\secpol.cfg
$c = 0; $len = 0; $maxAge = 999; $minAge = 0; $hist = 0
foreach ($line in $cfg) {
    if ($line -match '^PasswordComplexity\s*=\s*(-?\d+)') { $c = [int]$matches[1] }
    if ($line -match '^MinimumPasswordLength\s*=\s*(-?\d+)') { $len = [int]$matches[1] }
    if ($line -match '^MaximumPasswordAge\s*=\s*(-?\d+)') { $maxAge = [int]$matches[1] }
    if ($line -match '^MinimumPasswordAge\s*=\s*(-?\d+)') { $minAge = [int]$matches[1] }
    if ($line -match '^PasswordHistorySize\s*=\s*(-?\d+)') { $hist = [int]$matches[1] }
}
if ($c -eq 1 -and $len -ge 8 -and $maxAge -le 90 -and $maxAge -gt 0 -and $minAge -ge 1 -and $hist -ge 4) { 'True' } else { 'False' }

RemediationCommand:
$tempFile = "$env:TEMP\secpol_temp.cfg"
SecEdit.exe /export /cfg $tempFile /quiet
$cfg = Get-Content $tempFile -Raw
$keys = @{
    "PasswordComplexity" = "1"
    "MinimumPasswordLength" = "8"
    "MaximumPasswordAge" = "90"
    "MinimumPasswordAge" = "1"
    "PasswordHistorySize" = "4"
}
foreach ($k in $keys.Keys) {
    $v = $keys[$k]
    if ($cfg -notmatch $k) {
        $cfg = $cfg -replace '\[System Access\]', "[System Access]`r`n$k = $v"
    } else {
        $cfg = $cfg -replace "$k\s*=.*", "$k = $v"
    }
}
$cfg | Set-Content $tempFile -Encoding Unicode
SecEdit.exe /configure /db "$env:TEMP\secpol_temp.sdb" /cfg $tempFile /areas SECURITYPOLICY /quiet
Remove-Item $tempFile -ErrorAction SilentlyContinue
Remove-Item "$env:TEMP\secpol_temp.sdb" -ErrorAction SilentlyContinue
